begin;
create table if not exists hq.chart_of_accounts(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),code text not null,name text not null,account_class text not null check(account_class in('asset','liability','equity','revenue','expense')),parent_id uuid references hq.chart_of_accounts(id),active boolean not null default true,unique(legal_entity_id,code));
create table if not exists hq.accounting_periods(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),name text not null,starts_on date not null,ends_on date not null,status text not null default 'open' check(status in('open','review','closed','locked')),closed_by uuid references hq.employees(id),closed_at timestamptz,unique(legal_entity_id,starts_on,ends_on),check(ends_on>=starts_on));
create table if not exists hq.journal_entries(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),period_id uuid references hq.accounting_periods(id),entry_number bigint generated always as identity,entry_date date not null,description text not null,source_type text,source_id text,status text not null default 'draft' check(status in('draft','posted','reversed')),created_by uuid references hq.employees(id),posted_by uuid references hq.employees(id),posted_at timestamptz,created_at timestamptz not null default now());
create table if not exists hq.journal_lines(id uuid primary key default gen_random_uuid(),journal_entry_id uuid not null references hq.journal_entries(id) on delete cascade,account_id uuid not null references hq.chart_of_accounts(id),description text,debit numeric(18,2) not null default 0 check(debit>=0),credit numeric(18,2) not null default 0 check(credit>=0),check((debit>0 and credit=0) or (credit>0 and debit=0)));
create table if not exists hq.account_reconciliations(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),account_id uuid not null references hq.chart_of_accounts(id),period_id uuid references hq.accounting_periods(id),statement_balance numeric(18,2) not null,ledger_balance numeric(18,2) not null,status text not null default 'pending' check(status in('pending','matched','difference','approved')),reconciled_by uuid references hq.employees(id),approved_by uuid references hq.employees(id),created_at timestamptz not null default now(),check(reconciled_by is null or approved_by is null or reconciled_by<>approved_by));
do $$ declare t text; begin foreach t in array array['chart_of_accounts','accounting_periods','journal_entries','journal_lines','account_reconciliations'] loop execute format('alter table hq.%I enable row level security',t); execute format('revoke all on hq.%I from public,anon,authenticated',t); execute format('grant all on hq.%I to service_role',t); end loop; end $$;
insert into hq.chart_of_accounts(legal_entity_id,code,name,account_class) values
('10000000-0000-0000-0000-000000000001','11','Caixa e bancos','asset'),('10000000-0000-0000-0000-000000000001','21','Fornecedores','liability'),('10000000-0000-0000-0000-000000000001','31','Capital próprio','equity'),('10000000-0000-0000-0000-000000000001','41','Receitas operacionais','revenue'),('10000000-0000-0000-0000-000000000001','51','Despesas operacionais','expense') on conflict do nothing;
grant all on all sequences in schema hq to service_role;
commit;
